head.b:skin:
/* ============================================
   CSS VARIABLES
   ============================================ */
:root {
  --primary: #1a472a;
  --primary-light: #2d7a4a;
  --primary-dark: #0f2e1a;
  --secondary: #2d5a27;
  --accent: #8e6e53;
  --gold: #c19a3f;
  --gold-light: #d4b15f;
  --gold-gradient: linear-gradient(135deg, #c19a3f, #e8c96a);
  --light-green: #e8f5e8;
  --white: #ffffff;
  --dark: #1a1a1a;
  --text: #2c3e2c;
  --text-light: #5a6b5a;
  --light-bg: #f8fbf8;
  --gray-light: #f5f5f5;
  --gray-medium: #e0e0e0;
  --gray-dark: #757575;

  --bengali-font-size: 16px;
  --arabic-font-size: 1.6rem;
  --ui-font-size: 1rem;

  --font-bengali: 'Kalpurush', 'Hind Siliguri', sans-serif;
  --font-arabic: 'Amiri', 'Scheherazade New', serif;
  --font-ui: 'Hind Siliguri', sans-serif;

  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.06);
  --shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  --shadow-hover: 0 8px 32px rgba(0, 0, 0, 0.12);
  --shadow-large: 0 16px 48px rgba(0, 0, 0, 0.15);
  --shadow-glow: 0 0 40px rgba(193, 154, 63, 0.2);

  --rounded: 12px;
  --rounded-lg: 20px;
  --rounded-xl: 28px;
  --rounded-full: 50px;

  --transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  --transition-slow: all 0.6s cubic-bezier(0.25, 0.8, 0.25, 1);
  --transition-bounce: all 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);

  --header-gradient: linear-gradient(135deg, #1a472a, #2d7a4a);
}

/* Dark Mode */
[data-theme="dark"] {
  --primary: #3a9a5f;
  --primary-light: #4ab070;
  --primary-dark: #1a3a2a;
  --secondary: #4a8a5f;
  --accent: #b8957a;
  --gold: #e8c96a;
  --gold-light: #f0d97a;
  --light-green: #1a2a1a;
  --white: #1e1e1e;
  --dark: #f0f0f0;
  --text: #e0e0e0;
  --text-light: #b0b0b0;
  --light-bg: #121212;
  --gray-light: #2a2a2a;
  --gray-medium: #3a3a3a;
  --gray-dark: #a0a0a0;
  --shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
  --shadow-hover: 0 8px 32px rgba(0, 0, 0, 0.4);
  --shadow-large: 0 16px 48px rgba(0, 0, 0, 0.5);
  --shadow-glow: 0 0 40px rgba(232, 201, 106, 0.08);
}

/* ============================================
   RESET & BASE
   ============================================ */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-bengali);
  color: var(--text);
  background: var(--light-bg);
  line-height: 1.8;
  overflow: hidden;
  font-size: var(--bengali-font-size);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  transition: background-color 0.4s ease, color 0.4s ease;
  height: 100vh;
  width: 100vw;
}

::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::-webkit-scrollbar-track {
  background: var(--gray-light);
  border-radius: 10px;
}
::-webkit-scrollbar-thumb {
  background: var(--gold-gradient);
  border-radius: 10px;
}

/* ============================================
   FULL PAGE CHATBOT
   ============================================ */
.chatbot-fullpage {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  background: var(--white);
  z-index: 1000;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.chatbot-header-premium {
  background: var(--header-gradient);
  padding: 0.6rem 1.2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.4rem;
  min-height: 55px;
  flex-shrink: 0;
  position: relative;
  z-index: 10;
  box-shadow: 0 2px 15px rgba(0, 0, 0, 0.12);
}

.chatbot-header-premium::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--gold-gradient);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--white);
}

.header-brand .brand-icon {
  font-size: 1.4rem;
}

.header-brand .brand-text {
  font-size: 1.1rem;
  font-weight: 700;
}

.header-brand .brand-text span {
  color: var(--gold-light);
}

.header-controls {
  display: flex;
  gap: 0.3rem;
  flex-wrap: wrap;
}

.control-btn {
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.08);
  color: var(--white);
  padding: 0.25rem 0.6rem;
  border-radius: var(--rounded-full);
  cursor: pointer;
  transition: var(--transition);
  font-size: 0.7rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.2rem;
  backdrop-filter: blur(8px);
  font-family: var(--font-ui);
}

.control-btn:hover {
  background: rgba(255,255,255,0.25);
  transform: translateY(-1px);
}

.control-btn.active {
  background: var(--gold-gradient);
  color: var(--dark);
  border-color: var(--gold);
}

.chat-body-main {
  flex: 1;
  overflow-y: auto;
  padding: 0.8rem 1.2rem;
  background: var(--light-bg);
  scroll-behavior: smooth;
  min-height: 0;
}

.chat-body-main::-webkit-scrollbar {
  width: 5px;
}
.chat-body-main::-webkit-scrollbar-track {
  background: var(--gray-light);
}
.chat-body-main::-webkit-scrollbar-thumb {
  background: var(--gold-gradient);
  border-radius: 10px;
}

/* Welcome Section */
.welcome-section {
  text-align: center;
  padding: 0.5rem 0 1rem;
  animation: fadeInUp 0.6s ease;
}

.welcome-section .welcome-icon {
  font-size: 2.8rem;
  margin-bottom: 0.3rem;
  display: inline-block;
  animation: float 3s ease-in-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

.welcome-section h1 {
  font-size: 1.8rem;
  color: var(--primary);
  margin-bottom: 0.1rem;
  font-weight: 700;
}

.welcome-section h1 span {
  background: var(--gold-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.welcome-section p {
  font-size: 0.9rem;
  color: var(--text-light);
  max-width: 500px;
  margin: 0 auto 0.1rem;
}

.welcome-section .feature-badge {
  display: inline-block;
  background: var(--gold-gradient);
  color: var(--dark);
  padding: 0.15rem 0.8rem;
  border-radius: var(--rounded-full);
  font-size: 0.65rem;
  font-weight: 600;
  margin-top: 0.2rem;
}

.welcome-section .data-status {
  font-size: 0.7rem;
  color: var(--text-light);
  margin-top: 0.4rem;
  min-height: 1rem;
  transition: opacity 0.4s ease;
}

.welcome-section .data-status.error {
  color: #c62828;
  font-weight: 600;
}

.welcome-section .data-status.hidden {
  opacity: 0;
}

.quick-actions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 0.4rem;
  max-width: 750px;
  margin: 0.8rem auto 0;
}

.quick-action-premium {
  background: var(--white);
  border: 2px solid var(--gray-medium);
  padding: 0.4rem 0.5rem;
  border-radius: var(--rounded);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font-ui);
  font-weight: 600;
  font-size: 0.65rem;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.2rem;
  box-shadow: var(--shadow-sm);
}

.quick-action-premium:hover {
  border-color: var(--primary);
  background: rgba(26, 71, 42, 0.05);
  transform: translateY(-2px);
  box-shadow: var(--shadow-hover);
}

.quick-action-premium .qa-icon {
  font-size: 0.9rem;
}

.quick-action-premium.primary {
  border-color: var(--gold);
  background: var(--gold-gradient);
  color: var(--dark);
}

.quick-action-premium.primary:hover {
  box-shadow: 0 4px 15px rgba(193, 154, 63, 0.3);
}

/* Messages */
.message {
  margin-bottom: 0.8rem;
  padding: 0.6rem 1rem;
  border-radius: 1rem;
  max-width: 92%;
  word-wrap: break-word;
  line-height: 1.6;
  position: relative;
  animation: messageSlide 0.3s ease;
  font-size: 0.9rem;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

@keyframes messageSlide {
  from {
    opacity: 0;
    transform: translateY(15px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.message:hover {
  box-shadow: var(--shadow);
}

.message.user {
  background: linear-gradient(135deg, #e3f2fd, #bbdefb);
  margin-left: auto;
  border-bottom-right-radius: 0.3rem;
  color: #0d47a1;
  border: 1px solid #90caf9;
}

[data-theme="dark"] .message.user {
  background: linear-gradient(135deg, #1a2a4a, #0d1a3a);
  color: #90caf9;
  border-color: #1a3a5a;
}

.message.bot {
  background: linear-gradient(135deg, var(--light-green), #e8f5e8);
  margin-right: auto;
  border-bottom-left-radius: 0.3rem;
  color: var(--text);
  border: 1px solid #c8e6c9;
}

[data-theme="dark"] .message.bot {
  background: linear-gradient(135deg, #1a2a1a, #0d1a0d);
  border-color: #2a4a2a;
}

.message.bot.error {
  background: linear-gradient(135deg, #ffebee, #ffcdd2);
  border-color: #ef9a9a;
  color: #c62828;
}

.message.bot.success {
  background: linear-gradient(135deg, #e8f5e9, #c8e6c9);
  border-color: #81c784;
  color: #2e7d32;
}

.message.bot.info {
  background: linear-gradient(135deg, #e3f2fd, #bbdefb);
  border-color: #64b5f6;
  color: #0d47a1;
}

.message-timestamp {
  font-size: 0.55rem;
  color: var(--gray-dark);
  margin-top: 0.2rem;
  opacity: 0.6;
}

/* Blog Post Card - Enhanced */
.blog-post-card {
  background: var(--white);
  border-radius: var(--rounded);
  padding: 0.8rem 1rem;
  margin: 0.5rem 0;
  border-left: 4px solid var(--primary);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.blog-post-card:hover {
  box-shadow: var(--shadow-hover);
}

.blog-post-card .post-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 0.2rem;
  cursor: pointer;
}

.blog-post-card .post-title:hover {
  color: var(--gold);
}

.blog-post-card .post-excerpt {
  font-size: 0.8rem;
  color: var(--text-light);
  margin-bottom: 0.2rem;
}

.blog-post-card .post-meta {
  font-size: 0.65rem;
  color: var(--gray-dark);
}

.blog-post-card .post-full-content {
  font-size: 0.85rem;
  line-height: 1.8;
  color: var(--text);
  margin-top: 0.4rem;
  padding-top: 0.4rem;
  border-top: 1px solid var(--gray-medium);
  max-height: 400px;
  overflow-y: auto;
}

.blog-post-card .post-full-content::-webkit-scrollbar {
  width: 4px;
}
.blog-post-card .post-full-content::-webkit-scrollbar-thumb {
  background: var(--gold);
  border-radius: 10px;
}

.blog-post-card .post-full-content h2, 
.blog-post-card .post-full-content h3 {
  color: var(--primary);
  margin: 0.5rem 0 0.2rem;
  font-size: 0.95rem;
}

.blog-post-card .post-full-content img {
  max-width: 100%;
  border-radius: var(--rounded);
  margin: 0.3rem 0;
}

.blog-post-card .post-full-content blockquote {
  border-left: 3px solid var(--gold);
  padding-left: 0.8rem;
  margin: 0.3rem 0;
  font-style: italic;
  background: var(--light-green);
  padding: 0.5rem 0.8rem;
  border-radius: 0 var(--rounded) var(--rounded) 0;
  font-size: 0.85rem;
}

.blog-post-card .action-buttons {
  display: flex;
  gap: 0.3rem;
  flex-wrap: wrap;
  margin-top: 0.4rem;
}

.blog-post-card .action-btn {
  padding: 0.2rem 0.6rem;
  border: none;
  border-radius: var(--rounded-full);
  cursor: pointer;
  font-weight: 600;
  font-family: var(--font-ui);
  font-size: 0.65rem;
  transition: var(--transition);
}

.blog-post-card .action-btn.primary {
  background: var(--primary);
  color: var(--white);
}

.blog-post-card .action-btn.primary:hover {
  background: var(--primary-light);
  transform: translateY(-1px);
}

.blog-post-card .action-btn.gold {
  background: var(--gold-gradient);
  color: var(--dark);
}

.blog-post-card .action-btn.gold:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-sm);
}

.blog-post-card .action-btn.outline {
  background: transparent;
  border: 1px solid var(--gray-medium);
  color: var(--text);
}

.blog-post-card .action-btn.outline:hover {
  border-color: var(--primary);
  transform: translateY(-1px);
}

/* Hadith Card */
.hadith-card {
  background: var(--white);
  border-radius: var(--rounded);
  padding: 0.8rem 1rem;
  margin: 0.5rem 0;
  border-right: 4px solid var(--gold);
  box-shadow: var(--shadow-sm);
}

.hadith-card .hadith-text {
  font-size: 0.95rem;
  line-height: 1.8;
  font-style: italic;
  color: var(--text);
}

.hadith-card .hadith-translation {
  margin: 0.2rem 0;
  font-size: 0.85rem;
}

.hadith-card .hadith-source {
  font-size: 0.7rem;
  color: var(--gray-dark);
  margin-top: 0.2rem;
}

/* Knowledge Base Card */
.knowledge-card {
  background: var(--white);
  border-radius: var(--rounded);
  padding: 0.8rem 1rem;
  margin: 0.5rem 0;
  border-bottom: 3px solid var(--gold);
  box-shadow: var(--shadow-sm);
}

.knowledge-card .kb-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--primary);
}

.knowledge-card .kb-content {
  font-size: 0.85rem;
  line-height: 1.8;
  color: var(--text);
  margin-top: 0.2rem;
}

.knowledge-card .kb-source {
  font-size: 0.65rem;
  color: var(--gray-dark);
  margin-top: 0.2rem;
}

/* Prayer Card */
.prayer-card {
  background: var(--white);
  border-radius: var(--rounded);
  padding: 0.8rem 1rem;
  margin: 0.5rem 0;
  box-shadow: var(--shadow-sm);
}

.prayer-card .prayer-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.2rem;
}

.prayer-card .prayer-item {
  display: flex;
  justify-content: space-between;
  padding: 0.15rem 0.3rem;
  border-bottom: 1px solid var(--gray-light);
}

.prayer-card .prayer-item .name {
  font-weight: 600;
  color: var(--primary);
  font-size: 0.8rem;
}

.prayer-card .prayer-item .time {
  color: var(--text-light);
  font-size: 0.8rem;
}

/* Quiz Card */
.quiz-card {
  background: var(--white);
  border-radius: var(--rounded);
  padding: 0.8rem 1rem;
  margin: 0.5rem 0;
  box-shadow: var(--shadow-sm);
}

.quiz-card .question {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--primary);
  margin-bottom: 0.4rem;
}

.quiz-card .option-btn {
  display: block;
  width: 100%;
  padding: 0.4rem 0.6rem;
  margin: 0.15rem 0;
  border: 2px solid var(--gray-medium);
  border-radius: var(--rounded);
  background: var(--white);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font-ui);
  font-size: 0.8rem;
  text-align: left;
}

.quiz-card .option-btn:hover {
  border-color: var(--primary);
  background: rgba(26, 71, 42, 0.05);
}

.quiz-card .option-btn.correct {
  border-color: #4caf50;
  background: #e8f5e9;
}

.quiz-card .option-btn.wrong {
  border-color: #f44336;
  background: #ffebee;
}

.quiz-card .result {
  text-align: center;
  padding: 0.5rem;
  font-size: 0.95rem;
  font-weight: 600;
}

/* Typing Indicator */
.typing-indicator {
  display: flex;
  gap: 0.3rem;
  padding: 0.4rem 0.6rem;
  background: var(--gray-light);
  border-radius: var(--rounded);
  align-items: center;
  margin-bottom: 0.6rem;
  max-width: 60px;
}

.typing-indicator span {
  width: 6px;
  height: 6px;
  background: var(--primary);
  border-radius: 50%;
  animation: typingBounce 1.4s infinite;
}

.typing-indicator span:nth-child(2) {
  animation-delay: 0.2s;
}
.typing-indicator span:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes typingBounce {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
  30% { transform: translateY(-6px); opacity: 1; }
}

/* Input Area */
.chat-input-area {
  padding: 0.6rem 1.2rem;
  background: var(--white);
  border-top: 1px solid var(--gray-medium);
  display: flex;
  gap: 0.4rem;
  align-items: center;
  flex-wrap: wrap;
  flex-shrink: 0;
  min-height: 55px;
}

.chat-input-area .input-wrapper {
  flex: 1;
  position: relative;
  min-width: 100px;
}

.chat-input-area input {
  width: 100%;
  padding: 0.5rem 0.8rem;
  border: 2px solid var(--gray-medium);
  border-radius: var(--rounded-full);
  outline: none;
  font-family: var(--font-ui);
  font-size: 0.85rem;
  background: var(--white);
  color: var(--text);
  transition: var(--transition);
}

.chat-input-area input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(26, 71, 42, 0.08);
}

.chat-input-area input:disabled {
  background: var(--gray-light);
  cursor: not-allowed;
}

.chat-input-area .input-actions {
  display: flex;
  gap: 0.3rem;
  flex-wrap: wrap;
}

.input-btn {
  padding: 0.4rem 0.8rem;
  border: none;
  border-radius: var(--rounded-full);
  cursor: pointer;
  transition: var(--transition);
  font-weight: 600;
  font-family: var(--font-ui);
  font-size: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.2rem;
  min-height: 34px;
}

.input-btn.send {
  background: var(--gold-gradient);
  color: var(--dark);
  box-shadow: 0 3px 12px rgba(193, 154, 63, 0.25);
}

.input-btn.send:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(193, 154, 63, 0.35);
}

.input-btn.secondary {
  background: var(--primary);
  color: var(--white);
}

.input-btn.secondary:hover:not(:disabled) {
  background: var(--primary-light);
  transform: translateY(-2px);
}

.input-btn.outline {
  background: transparent;
  border: 1px solid var(--gray-medium);
  color: var(--text);
}

.input-btn.outline:hover:not(:disabled) {
  border-color: var(--primary);
  background: rgba(26, 71, 42, 0.05);
  transform: translateY(-2px);
}

.input-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none !important;
}

/* Search Highlight */
.search-highlight {
  background: var(--gold);
  color: var(--dark);
  padding: 0.05rem 0.2rem;
  border-radius: 3px;
  font-weight: 600;
}

.search-result-item {
  background: var(--white);
  padding: 0.5rem 0.8rem;
  margin: 0.3rem 0;
  border-radius: var(--rounded);
  border-left: 3px solid var(--gold);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.search-result-item:hover {
  box-shadow: var(--shadow);
  transform: translateX(3px);
}

.search-result-sura {
  font-weight: 600;
  color: var(--primary);
  margin-bottom: 0.1rem;
  font-size: 0.8rem;
}

.search-result-text {
  color: var(--text);
  line-height: 1.6;
  font-size: 0.8rem;
}

/* ============================================
   TAFSIR MODAL
   ============================================ */
.tafsir-modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(8px);
  z-index: 9999;
  justify-content: center;
  align-items: center;
  padding: 1.5rem;
}

.tafsir-modal-overlay.active {
  display: flex;
  animation: fadeIn 0.3s ease;
}

.tafsir-modal-content {
  background: var(--white);
  border-radius: var(--rounded-xl);
  max-width: 750px;
  width: 100%;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-large);
  animation: scaleIn 0.3s ease;
  overflow: hidden;
}

.tafsir-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.8rem 1.2rem;
  background: var(--header-gradient);
  color: white;
}

.tafsir-modal-header h3 {
  color: white;
  font-size: 1rem;
  margin: 0;
}

.tafsir-modal-header .close-modal {
  background: rgba(255,255,255,0.15);
  border: none;
  color: white;
  cursor: pointer;
  font-size: 1.1rem;
  padding: 0.15rem 0.5rem;
  border-radius: var(--rounded);
  transition: var(--transition);
}

.tafsir-modal-header .close-modal:hover {
  background: rgba(255,255,255,0.3);
  transform: rotate(90deg);
}

.tafsir-modal-body {
  padding: 1rem;
  overflow-y: auto;
  flex: 1;
  line-height: 1.8;
  color: var(--text);
}

.tafsir-modal-body .verse-arabic {
  font-size: 1.2rem;
  text-align: right;
  padding: 0.8rem;
  background: var(--light-green);
  border-radius: var(--rounded);
  border-right: 4px solid var(--gold);
  font-family: var(--font-arabic);
  direction: rtl;
  line-height: 2;
  margin-bottom: 0.8rem;
}

.tafsir-modal-body .verse-translation {
  padding: 0.5rem 0.8rem;
  background: #f8f9fa;
  border-radius: var(--rounded);
  border-left: 4px solid var(--primary);
  margin-bottom: 0.8rem;
}

.tafsir-modal-body .tafsir-text {
  padding: 0.8rem;
  background: #fffde7;
  border-radius: var(--rounded);
  border-left: 4px solid var(--gold);
  line-height: 1.8;
}

.tafsir-modal-body .tafsir-source {
  margin-top: 0.8rem;
  font-style: italic;
  color: var(--gray-dark);
  font-size: 0.75rem;
  border-top: 1px solid var(--gray-medium);
  padding-top: 0.8rem;
}

/* ============================================
   SETTINGS PANEL
   ============================================ */
.settings-panel-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(8px);
  z-index: 9998;
  justify-content: flex-end;
  animation: fadeIn 0.3s ease;
}

.settings-panel-overlay.active {
  display: flex;
}

.settings-panel-content {
  background: var(--white);
  width: 350px;
  max-width: 90vw;
  height: 100vh;
  padding: 1.2rem;
  overflow-y: auto;
  animation: slideInRight 0.3s ease;
}

@keyframes slideInRight {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

.settings-panel-content .settings-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
  padding-bottom: 0.8rem;
  border-bottom: 2px solid var(--gray-medium);
}

.settings-panel-content .settings-header h2 {
  font-size: 1.2rem;
  color: var(--primary);
  margin: 0;
}

.settings-panel-content .settings-header .close-settings {
  background: none;
  border: none;
  font-size: 1.3rem;
  cursor: pointer;
  color: var(--gray-dark);
  transition: var(--transition);
  padding: 0.2rem;
}

.settings-panel-content .settings-header .close-settings:hover {
  color: var(--primary);
  transform: rotate(90deg);
}

.settings-panel-content .setting-group {
  margin-bottom: 1rem;
}

.settings-panel-content .setting-group label {
  display: block;
  font-weight: 600;
  color: var(--primary);
  margin-bottom: 0.2rem;
  font-size: 0.9rem;
}

.settings-panel-content .setting-group select,
.settings-panel-content .setting-group input[type="text"] {
  width: 100%;
  padding: 0.4rem 0.6rem;
  border: 2px solid var(--gray-medium);
  border-radius: var(--rounded);
  font-family: var(--font-ui);
  font-size: 0.85rem;
  transition: var(--transition);
  background: var(--white);
  color: var(--text);
}

.settings-panel-content .setting-group select:focus,
.settings-panel-content .setting-group input[type="text"]:focus {
  border-color: var(--primary);
  outline: none;
  box-shadow: 0 0 0 3px rgba(26, 71, 42, 0.08);
}

.settings-panel-content .setting-group .setting-desc {
  font-size: 0.7rem;
  color: var(--gray-dark);
  margin-top: 0.15rem;
  line-height: 1.4;
}

.settings-panel-content .setting-group .checkbox-group {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.settings-panel-content .setting-group .checkbox-group input[type="checkbox"] {
  width: 15px;
  height: 15px;
  accent-color: var(--primary);
}

.settings-panel-content .btn-reset {
  width: 100%;
  padding: 0.6rem;
  background: var(--primary);
  color: var(--white);
  border: none;
  border-radius: var(--rounded);
  font-weight: 600;
  font-family: var(--font-ui);
  font-size: 0.85rem;
  cursor: pointer;
  transition: var(--transition);
}

.settings-panel-content .btn-reset:hover {
  background: var(--primary-light);
  transform: translateY(-2px);
}

/* ============================================
   SURA LIST PANEL
   ============================================ */
.sura-panel-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(8px);
  z-index: 9998;
  justify-content: flex-start;
  animation: fadeIn 0.3s ease;
}

.sura-panel-overlay.active {
  display: flex;
}

.sura-panel-content {
  background: var(--white);
  width: 350px;
  max-width: 90vw;
  height: 100vh;
  padding: 1.2rem;
  overflow-y: auto;
  animation: slideInLeft 0.3s ease;
}

@keyframes slideInLeft {
  from { transform: translateX(-100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

.sura-panel-content .sura-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.8rem;
  padding-bottom: 0.8rem;
  border-bottom: 2px solid var(--gray-medium);
}

.sura-panel-content .sura-header h2 {
  font-size: 1.2rem;
  color: var(--primary);
  margin: 0;
}

.sura-panel-content .sura-header .close-sura {
  background: none;
  border: none;
  font-size: 1.3rem;
  cursor: pointer;
  color: var(--gray-dark);
  transition: var(--transition);
  padding: 0.2rem;
}

.sura-panel-content .sura-header .close-sura:hover {
  color: var(--primary);
  transform: rotate(90deg);
}

.sura-panel-content .sura-search {
  width: 100%;
  padding: 0.4rem 0.6rem;
  border: 2px solid var(--gray-medium);
  border-radius: var(--rounded-full);
  font-family: var(--font-ui);
  font-size: 0.85rem;
  transition: var(--transition);
  background: var(--white);
  color: var(--text);
  margin-bottom: 0.8rem;
}

.sura-panel-content .sura-search:focus {
  border-color: var(--primary);
  outline: none;
  box-shadow: 0 0 0 3px rgba(26, 71, 42, 0.08);
}

.sura-panel-content .sura-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(60px, 1fr));
  gap: 0.3rem;
}

.sura-panel-content .sura-grid .sura-item {
  background: var(--light-green);
  border: 2px solid transparent;
  border-radius: var(--rounded);
  padding: 0.3rem 0.15rem;
  text-align: center;
  cursor: pointer;
  transition: var(--transition);
  font-weight: 600;
  color: var(--primary);
  font-size: 0.65rem;
  font-family: var(--font-ui);
}

.sura-panel-content .sura-grid .sura-item:hover {
  background: var(--primary);
  color: var(--white);
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.sura-panel-content .sura-grid .sura-item small {
  display: block;
  font-weight: 400;
  font-size: 0.5rem;
  opacity: 0.6;
  margin-top: 1px;
}

/* ============================================
   ANIMATIONS
   ============================================ */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* ============================================
   RESPONSIVE DESIGN
   ============================================ */
@media (max-width: 768px) {
  .chatbot-header-premium { padding: 0.4rem 0.8rem; min-height: 48px; }
  .header-brand .brand-text { font-size: 0.9rem; }
  .control-btn { font-size: 0.6rem; padding: 0.2rem 0.4rem; }
  .chat-body-main { padding: 0.5rem 0.8rem; }
  .chat-input-area { padding: 0.4rem 0.8rem; min-height: 48px; }
  .input-btn { font-size: 0.65rem; padding: 0.3rem 0.6rem; min-height: 30px; }
  .welcome-section h1 { font-size: 1.4rem; }
  .welcome-section p { font-size: 0.8rem; }
  .quick-actions-grid { grid-template-columns: repeat(auto-fit, minmax(90px, 1fr)); gap: 0.3rem; }
  .quick-action-premium { padding: 0.3rem 0.4rem; font-size: 0.6rem; }
  .message { font-size: 0.8rem; padding: 0.5rem 0.8rem; max-width: 95%; }
  .settings-panel-content, .sura-panel-content { width: 100%; max-width: 100%; padding: 0.8rem; }
}

@media (max-width: 480px) {
  .header-brand .brand-text { font-size: 0.75rem; }
  .header-brand .brand-icon { font-size: 1.1rem; }
  .control-btn { font-size: 0.5rem; padding: 0.15rem 0.35rem; }
  .welcome-section h1 { font-size: 1.1rem; }
  .quick-actions-grid { grid-template-columns: 1fr 1fr; gap: 0.2rem; }
  .quick-action-premium { font-size: 0.55rem; padding: 0.2rem 0.3rem; }
  .input-btn { font-size: 0.6rem; padding: 0.25rem 0.5rem; min-height: 26px; }
  .settings-panel-content, .sura-panel-content { padding: 0.6rem; }
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
  :root {
    --primary: #000000;
    --gold: #ffd700;
    --text: #000000;
    --light-bg: #ffffff;
  }
  .chatbot-header-premium { border-bottom: 3px solid #000; }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

body.script:
//
// ============================================================
// COMPLETE CHATBOT APPLICATION - FIXED VERSION
// ============================================================

(function() {
  'use strict';

  // ==================== STATE ====================
  var state = {
    quranData: [],
    arabicData: [],
    tafsirData: {},
    blogPosts: [],
    hadithData: [],
    knowledgeBase: [],
    currentAya: null,
    isLoading: false,
    isVoiceActive: false,
    recognition: null,
    audioSettings: { speed: '1', autoPlay: false },
    displaySettings: { showTransliteration: false },
    isDark: false,
    quizState: null,
    expandedPosts: {},
    dataLoaded: false,
    welcomeVisible: true
  };

  // ==================== DOM REFS ====================
  var dom = {
    body: document.getElementById('chat-body'),
    messages: document.getElementById('messages-container'),
    input: document.getElementById('chat-input'),
    sendBtn: document.getElementById('send-btn'),
    clearBtn: document.getElementById('clear-btn'),
    tafsirBtn: document.getElementById('tafsir-btn'),
    voiceBtn: document.getElementById('voice-btn'),
    themeToggle: document.getElementById('theme-toggle'),
    themeIcon: document.getElementById('theme-icon'),
    suraPanelBtn: document.getElementById('sura-panel-btn'),
    settingsPanelBtn: document.getElementById('settings-panel-btn'),
    suraPanel: document.getElementById('sura-panel'),
    settingsPanel: document.getElementById('settings-panel'),
    closeSura: document.getElementById('close-sura'),
    closeSettings: document.getElementById('close-settings'),
    suraSearch: document.getElementById('sura-search'),
    suraGrid: document.getElementById('sura-grid'),
    tafsirModal: document.getElementById('tafsir-modal'),
    closeTafsir: document.getElementById('close-tafsir-modal'),
    tafsirBody: document.getElementById('tafsir-modal-body'),
    tafsirTitle: document.getElementById('tafsir-modal-title'),
    welcomeSection: document.getElementById('welcome-section'),
    dataStatus: document.getElementById('data-status')
  };

  // ==================== UTILITY FUNCTIONS ====================
  function getTimestamp() {
    return new Date().toLocaleTimeString('bn-BD', { 
      hour: '2-digit', 
      minute: '2-digit',
      hour12: true 
    });
  }

  function scrollToBottom() {
    dom.body.scrollTop = dom.body.scrollHeight;
  }

  function setDataStatus(text, isError) {
    if (!dom.dataStatus) return;
    dom.dataStatus.textContent = text || '';
    dom.dataStatus.classList.toggle('error', !!isError);
    dom.dataStatus.classList.remove('hidden');
  }

  function fadeDataStatus() {
    if (!dom.dataStatus) return;
    setTimeout(function() {
      dom.dataStatus.classList.add('hidden');
    }, 1800);
  }

  function convertNumbers(input) {
    var map = {'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9'};
    var output = input;
    for (var bn in map) {
      if (map.hasOwnProperty(bn)) {
        output = output.replace(new RegExp(bn, 'g'), map[bn]);
      }
    }
    return output;
  }

  function getSurahAyahCount(surah) {
    var counts = {
      1:7,2:286,3:200,4:176,5:120,6:165,7:206,8:75,9:129,10:109,
      11:123,12:111,13:43,14:52,15:99,16:128,17:111,18:110,19:98,20:135,
      21:112,22:78,23:118,24:64,25:77,26:227,27:93,28:88,29:69,30:60,
      31:34,32:30,33:73,34:54,35:45,36:83,37:182,38:88,39:75,40:85,
      41:54,42:53,43:89,44:59,45:37,46:35,47:38,48:29,49:18,50:45,
      51:60,52:49,53:62,54:55,55:78,56:96,57:29,58:22,59:24,60:13,
      61:14,62:11,63:11,64:18,65:12,66:12,67:30,68:52,69:52,70:44,
      71:28,72:28,73:20,74:56,75:40,76:31,77:50,78:40,79:46,80:42,
      81:29,82:19,83:36,84:25,85:22,86:17,87:19,88:26,89:30,90:20,
      91:15,92:21,93:11,94:8,95:8,96:19,97:5,98:8,99:8,100:11,
      101:11,102:8,103:3,104:9,105:5,106:4,107:7,108:3,109:6,110:3,
      111:5,112:4,113:5,114:6
    };
    return counts[surah] || 0;
  }

  function getSurahName(num) {
    var names = [
      "আল-ফাতিহা","আল-বাকারা","আল-ইমরান","আন-নিসা","আল-মায়িদাহ",
      "আল-আন'আম","আল-আ'রাফ","আল-আনফাল","আত-তাওবাহ","ইউনুস",
      "হুদ","ইউসুফ","আর-রাদ","ইবরাহিম","আল-হিজর","আন-নাহল",
      "আল-ইসরা","আল-কাহফ","মারইয়াম","তাহা","আল-আম্বিয়া",
      "আল-হাজ্জ","আল-মুমিনুন","আন-নূর","আল-ফুরকান","আশ-শু'আরা",
      "আন-নামল","আল-কাসাস","আল-আনকাবুত","আর-রুম","লুকমান",
      "আস-সাজদাহ","আল-আহযাব","সাবা","ফাতির","ইয়াসিন",
      "আস-সাফফাত","সাদ","আয-যুমার","গাফির","ফুসসিলাত",
      "আশ-শুরা","আয-যুখরুফ","আদ-দুখান","আল-জাসিয়াহ","আল-আহকাফ",
      "মুহাম্মদ","আল-ফাতহ","আল-হুজুরাত","কাফ","আয-যারিয়াত",
      "আত-তুর","আন-নাজম","আল-কামার","আর-রহমান","আল-ওয়াকিয়াহ",
      "আল-হাদীদ","আল-মুজাদিলাহ","আল-হাশর","আল-মুমতাহিনাহ","আস-সাফ",
      "আল-জুমু'আহ","আল-মুনাফিকুন","আত-তাগাবুন","আত-তালাক","আত-তাহরীম",
      "আল-মুলক","আল-কালাম","আল-হাক্কাহ","আল-মা'আরিজ","নূহ",
      "আল-জিন","আল-মুজাম্মিল","আল-মুদ্দাস্সির","আল-কিয়ামাহ","আল-ইনসান",
      "আল-মুরসালাত","আন-নাবা","আন-নাজি'আত","আবাসা","আত-তাকভীর",
      "আল-ইনফিতার","আল-মুতাফফিফীন","আল-ইনশিকাক","আল-বুরূজ","আত-তারিক",
      "আল-আ'লা","আল-গাশিয়াহ","আল-ফাজর","আল-বালাদ","আশ-শামস",
      "আল-লাইল","আদ-দুহা","আল-ইনশিরাহ","আত-তীন","আল-আলাক",
      "আল-কাদর","আল-বাইয়্যিনাহ","আয-যিলযাল","আল-আদিয়াত","আল-কারি'আহ",
      "আত-তাকাসুর","আল-আসর","আল-হুমাজাহ","আল-ফীল","কুরাইশ",
      "আল-মাউন","আল-কাওসার","আল-কাফিরুন","আন-নাসর","আল-মাসাদ",
      "আল-ইখলাস","আল-ফালাক","আন-নাস"
    ];
    return names[num - 1] || "সূরা " + num;
  }

  // ==================== MESSAGE FUNCTIONS ====================
  function addMessage(text, isUser, type, isHTML) {
    isUser = isUser || false;
    type = type || 'normal';
    isHTML = isHTML || false;

    // Hide welcome section on first message
    if (dom.welcomeSection && state.welcomeVisible) {
      dom.welcomeSection.style.display = 'none';
      state.welcomeVisible = false;
    }

    var div = document.createElement('div');
    div.className = 'message ' + (isUser ? 'user' : 'bot');
    if (!isUser && type !== 'normal') {
      div.classList.add(type);
    }

    if (isHTML) {
      div.innerHTML = text + '<div class="message-timestamp">' + getTimestamp() + '</div>';
    } else {
      div.textContent = text;
      div.innerHTML += '<div class="message-timestamp">' + getTimestamp() + '</div>';
    }

    dom.messages.appendChild(div);
    scrollToBottom();
    return div;
  }

  function addUserMessage(text) {
    return addMessage(text, true);
  }

  function addBotMessage(text, type, isHTML) {
    type = type || 'normal';
    isHTML = isHTML || false;
    return addMessage(text, false, type, isHTML);
  }

  function showTyping() {
    var div = document.createElement('div');
    div.id = 'typing-indicator';
    div.className = 'typing-indicator';
    div.innerHTML = '<span></span><span></span><span></span>';
    dom.messages.appendChild(div);
    scrollToBottom();
  }

  function removeTyping() {
    var el = document.getElementById('typing-indicator');
    if (el) el.remove();
  }

  function clearChat() {
    dom.messages.innerHTML = '';
    // Show welcome section again
    if (dom.welcomeSection) {
      dom.welcomeSection.style.display = 'block';
      state.welcomeVisible = true;
    }
    state.currentAya = null;
    state.quizState = null;
    dom.input.value = '';
    dom.input.focus();
  }

  // ==================== LOAD QURAN DATA ====================
  async function loadQuranData() {
    try {
      // Show a quiet inline status on the welcome screen instead of a
      // chat bubble, so the welcome screen (with quick actions) stays
      // visible while data loads in the background.
      setDataStatus('⏳ কুরআন ডেটা লোড হচ্ছে...', false);

      var [quranRes, arabicRes, tafsirRes] = await Promise.all([
        fetch("https://raw.githubusercontent.com/Akter-Molla/Quran-bot-bn/main/ayats_bn.json"),
        fetch("https://raw.githubusercontent.com/alQuranBD/Database/master/json/ayats_ar.json"),
        fetch("https://raw.githubusercontent.com/Akter-Molla/Quran-bot-bn/main/Tafseer_ibn_Kathir.json")
      ]);

      if (!quranRes.ok || !arabicRes.ok || !tafsirRes.ok) {
        throw new Error('ডেটা লোড করতে সমস্যা হয়েছে');
      }

      state.quranData = await quranRes.json();
      state.arabicData = await arabicRes.json();
      state.tafsirData = await tafsirRes.json();

      loadHadithData();
      loadKnowledgeBase();
      loadBlogPosts();

      state.dataLoaded = true;
      setDataStatus('✅ ডেটা প্রস্তুত', false);
      fadeDataStatus();

    } catch (error) {
      console.error('ডেটা লোডিং ত্রুটি:', error);
      setDataStatus('❌ ডেটা লোড করতে সমস্যা হয়েছে। পৃষ্ঠাটি রিফ্রেশ করুন।', true);
    }
  }

