  // ==================== BLOG POSTS ====================
  function loadBlogPosts() {
    var blogUrl = window.location.origin;
    var feedUrl = blogUrl + '/feeds/posts/default?alt=json&max-results=10';

    fetch(feedUrl)
      .then(function(response) {
        if (!response.ok) throw new Error('Blog feed not available');
        return response.json();
      })
      .then(function(data) {
        if (data && data.feed && data.feed.entry) {
          state.blogPosts = data.feed.entry.map(function(entry) {
            var content = entry.content ? entry.content.$t || '' : '';
            var summary = entry.summary ? entry.summary.$t || '' : '';
            // Clean HTML for display
            content = cleanHtmlContent(content);
            summary = cleanHtmlContent(summary) || content.substring(0, 200) + '...';

            return {
              title: entry.title.$t || '',
              content: content,
              summary: summary,
              published: entry.published ? entry.published.$t || '' : '',
              link: entry.link ? entry.link.find(function(l) { return l.rel === 'alternate'; })?.href || '' : '',
              author: entry.author ? entry.author[0]?.name?.$t || '' : '',
              id: entry.id ? entry.id.$t || '' : 'post-' + Math.random().toString(36).substr(2, 9)
            };
          });
          console.log('✅ Blog posts loaded:', state.blogPosts.length);
        }
      })
      .catch(function(error) {
        console.log('Blog posts not available:', error);
        // Sample blog posts
        state.blogPosts = [
          {
            title: 'কুরআনের গুরুত্ব ও ফযিলত',
            content: 'কুরআন হলো মানবজাতির জন্য সর্বশেষ ঐশী গ্রন্থ এবং মুসলিমদের জীবনযাপনের পূর্ণাঙ্গ দিকনির্দেশনা। কুরআন অধ্যয়নের গুরুত্ব অপরিসীম।',
            summary: 'কুরআন হলো মানবজাতির জন্য সর্বশেষ ঐশী গ্রন্থ এবং মুসলিমদের জীবনযাপনের দিকনির্দেশনা...',
