  function cleanHtmlContent(html) {
    if (!html) return '';
    // Remove scripts
    html = html.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
    // Remove styles
    html = html.replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '');
    // Convert common tags
    html = html.replace(/<br\s*\/?>/gi, '\n');
    html = html.replace(/<\/p>/gi, '\n\n');
    html = html.replace(/<p>/gi, '');
    html = html.replace(/<div[^>]*>/gi, '');
    html = html.replace(/<\/div>/gi, '');
    html = html.replace(/<b[^>]*>/gi, '**');
    html = html.replace(/<\/b>/gi, '**');
    html = html.replace(/<strong[^>]*>/gi, '**');
    html = html.replace(/<\/strong>/gi, '**');
    html = html.replace(/<i[^>]*>/gi, '*');
    html = html.replace(/<\/i>/gi, '*');
    html = html.replace(/<em[^>]*>/gi, '*');
    html = html.replace(/<\/em>/gi, '*');
    // Remove remaining tags
    html = html.replace(/<[^>]*>/g, '');
    return html.trim();
  }

  // ==================== QUERY PROCESSING ====================
  function processQuery(query) {
    if (state.isLoading) return;

    var trimmed = query.trim();
    if (!trimmed) {
      addBotMessage('❌ অনুগ্রহ করে একটি প্রশ্ন লিখুন।', 'error');
      return;
    }

    addUserMessage(trimmed);
    dom.input.value = '';
    dom.input.focus();

    showTyping();
    state.isLoading = true;

    setTimeout(function() {
      removeTyping();
      state.isLoading = false;

      try {
        var normalized = convertNumbers(trimmed);
        var lowerQuery = trimmed.toLowerCase();

        // Command detection
        if (/^(\d+)[:\.\/,](\d+)$/.test(normalized) || /^সূরা\s*(\d+)\s*আয়াত\s*(\d+)$/i.test(normalized)) {
          handleSurahAya(normalized);
        } else if (lowerQuery.indexOf('হাদিস') !== -1 || lowerQuery.indexOf('hadith') !== -1 || lowerQuery.indexOf('হাদীস') !== -1) {
          if (lowerQuery.indexOf('সব') !== -1 || lowerQuery.indexOf('all') !== -1) {
            showAllHadith();
          } else {
            showRandomHadith();
          }
        } else if (lowerQuery.indexOf('ব্লগ') !== -1 || lowerQuery.indexOf('blog') !== -1 || lowerQuery.indexOf('পোস্ট') !== -1) {
          showBlogPosts();
        } else if (lowerQuery.indexOf('সালাত') !== -1 || lowerQuery.indexOf('নামাজ') !== -1 || lowerQuery.indexOf('ওয়াক্ত') !== -1 || lowerQuery.indexOf('prayer') !== -1) {
          showPrayerTimes();
        } else if (lowerQuery.indexOf('কুইজ') !== -1 || lowerQuery.indexOf('quiz') !== -1 || lowerQuery.indexOf('প্রশ্ন') !== -1) {
          startQuiz();
        } else if (lowerQuery.indexOf('জ্ঞান') !== -1 || lowerQuery.indexOf('knowledge') !== -1 || lowerQuery.indexOf('শিখা') !== -1) {
          showKnowledgeBase();
        } else if (lowerQuery.indexOf('গাইড') !== -1 || lowerQuery.indexOf('guide') !== -1 || lowerQuery.indexOf('সাহায্য') !== -1 || lowerQuery.indexOf('help') !== -1) {
          showGuide();
        } else if (trimmed.length >= 2) {
          handleKeywordSearch(trimmed);
        } else if (/সালাম|assalam|hello|hi|হ্যালো|নমস্কার|আদাব/i.test(trimmed)) {
          handleGreeting();
        } else {
          // Search knowledge base
          var kbResult = searchKnowledgeBase(trimmed);
          if (kbResult) {
            showKnowledgeItem(kbResult);
          } else {
            addBotMessage('🤔 "' + trimmed + '" - আমি এই প্রশ্নের উত্তর দিতে পারছি না।\n\nআপনি চাইলে:\n• সূরা:আয়াত (যেমন: 2:255)\n• হাদিস দেখতে "হাদিস" লিখুন\n• ব্লগ পোস্ট দেখতে "ব্লগ" লিখুন\n• নামাজের সময় জানতে "নামাজ" লিখুন\n• কুইজ খেলতে "কুইজ" লিখুন\n• জ্ঞান দেখতে "জ্ঞান" লিখুন\n• গাইড দেখতে "গাইড" লিখুন', 'info');
          }
        }
      } catch (error) {
        console.error('Query error:', error);
        addBotMessage('❌ প্রক্রিয়াকরণে সমস্যা হয়েছে। আবার চেষ্টা করুন।', 'error');
      }
    }, 800);
  }

  // ==================== KNOWLEDGE BASE SEARCH ====================
  function searchKnowledgeBase(query) {
    var q = query.toLowerCase();
    for (var i = 0; i < state.knowledgeBase.length; i++) {
      var item = state.knowledgeBase[i];
      if (item.title.toLowerCase().indexOf(q) !== -1 || item.content.toLowerCase().indexOf(q) !== -1) {
        return item;
      }
    }
    return null;
  }

  function showKnowledgeItem(item) {
    var html = '<div class="knowledge-card">';
    html += '<div class="kb-title">📚 ' + item.title + '</div>';
    html += '<div class="kb-content">' + item.content.replace(/\n/g, '<br>') + '</div>';
    html += '<div class="kb-source">📖 ' + item.source + '</div>';
    html += '</div>';
    addBotMessage(html, 'normal', true);
  }

  function showKnowledgeBase() {
    var html = '<strong>📚 ইসলামিক জ্ঞান ভাণ্ডার</strong><br><br>';
    state.knowledgeBase.forEach(function(item) {
      html += '<div class="knowledge-card">';
      html += '<div class="kb-title">📖 ' + item.title + '</div>';
      html += '<div class="kb-content">' + item.content.replace(/\n/g, '<br>') + '</div>';
      html += '<div class="kb-source">📖 ' + item.source + '</div>';
      html += '</div>';
    });
    addBotMessage(html, 'normal', true);
  }

