  // ==================== SURAH AYA HANDLER ====================
  function handleSurahAya(query) {
    var match = query.match(/^(\d+)[:\.\/,](\d+)$/) || 
                 query.match(/^সূরা\s*(\d+)\s*আয়াত\s*(\d+)$/i);

    if (match) {
      var sura = match[1];
      var aya = match[2];
      var result = state.quranData.find(function(a) { return a.sura === sura && a.aya === aya; });

      if (result) {
        state.currentAya = result;
        displayAyaResult(result);

        if (state.audioSettings.autoPlay) {
          setTimeout(function() { playAudio(sura, aya); }, 1000);
        }
      } else {
        addBotMessage('❌ সূরা ' + sura + ', আয়াত ' + aya + ' পাওয়া যায়নি।', 'error');
      }
    }
  }

  // ==================== KEYWORD SEARCH ====================
  function handleKeywordSearch(query) {
    var words = query.toLowerCase().split(/\s+/);
    var results = [];

    state.quranData.forEach(function(aya) {
      var text = aya.text.toLowerCase();
      var matchCount = 0;
      var highlighted = aya.text;

      words.forEach(function(word) {
        var regex = new RegExp(word, 'gi');
        var matches = text.match(regex);
        if (matches) {
          matchCount += matches.length;
          highlighted = highlighted.replace(regex, function(m) { return '<span class="search-highlight">' + m + '</span>'; });
        }
      });

      if (matchCount > 0) {
        results.push({ sura: aya.sura, aya: aya.aya, text: aya.text, matchCount: matchCount, highlighted: highlighted });
      }
    });

    results.sort(function(a, b) { return b.matchCount - a.matchCount; });
    var top = results.slice(0, 8);

    if (top.length === 0) {
      var kbResult = searchKnowledgeBase(query);
      if (kbResult) {
        showKnowledgeItem(kbResult);
        return;
      }
      addBotMessage('❌ "' + query + '" এর জন্য কোন ফলাফল পাওয়া যায়নি।', 'error');
      return;
    }

    var html = '<strong>"' + query + '" এর জন্য ' + top.length + 'টি আয়াত পাওয়া গেছে</strong><br><br>';
    top.forEach(function(r, i) {
      html += '<div class="search-result-item"><div class="search-result-sura">' + (i+1) + '. সূরা ' + r.sura + ', আয়াত ' + r.aya + ' (' + r.matchCount + 'টি মিল)</div><div class="search-result-text">' + r.highlighted + '</div><button onclick="window.selectAya(\'' + r.sura + '\',\'' + r.aya + '\')" style="margin-top:4px;background:var(--gold);color:#000;border:none;padding:3px 8px;border-radius:5px;cursor:pointer;font-weight:600;font-size:0.75rem;">নির্বাচন</button></div>';
    });

    addBotMessage(html, 'normal', true);
  }

  // ==================== DISPLAY AYA RESULT ====================
  function displayAyaResult(aya) {
    var arabic = state.arabicData.find(function(a) { return a.sura === aya.sura && a.VerseIDAr === aya.aya; });

    var html = '<strong>সূরা ' + aya.sura + ', আয়াত ' + aya.aya + '</strong>';
    if (arabic && arabic.ayat) {
      html += '<div class="arabic-text" style="font-family:var(--font-arabic);font-size:var(--arabic-font-size);text-align:right;direction:rtl;padding:0.8rem;background:var(--light-green);border-radius:var(--rounded);margin:0.4rem 0;line-height:2.2;">' + arabic.ayat + '</div>';
    }
    html += '<div style="padding:0.5rem 0.8rem;background:#f8f9fa;border-radius:var(--rounded);border-left:4px solid var(--primary);margin:0.4rem 0;">' + aya.text + '</div>';
    html += '<div style="display:flex;gap:0.3rem;flex-wrap:wrap;margin-top:0.4rem;">';
    html += '<button onclick="window.showTafsir(\'' + aya.sura + '\',\'' + aya.aya + '\')" style="background:var(--primary);color:#fff;border:none;padding:4px 10px;border-radius:5px;cursor:pointer;font-weight:600;font-family:var(--font-ui);font-size:0.75rem;">📖 তাফসীর</button>';
    html += '<button onclick="window.playAudio(\'' + aya.sura + '\',\'' + aya.aya + '\')" style="background:var(--secondary);color:#fff;border:none;padding:4px 10px;border-radius:5px;cursor:pointer;font-weight:600;font-family:var(--font-ui);font-size:0.75rem;">🎧 শুনুন</button>';
    html += '<button onclick="window.copyAya(\'' + aya.sura + '\',\'' + aya.aya + '\')" style="background:var(--gold);color:#000;border:none;padding:4px 10px;border-radius:5px;cursor:pointer;font-weight:600;font-family:var(--font-ui);font-size:0.75rem;">📋 কপি</button>';
    html += '</div>';

    addBotMessage(html, 'normal', true);
  }

  // ==================== TAFSIR ====================
  function showTafsirModal(sura, aya) {
    var tafsir = state.tafsirData[sura + ':' + aya];
    var arabic = state.arabicData.find(function(a) { return a.sura === sura && a.VerseIDAr === aya; });
    var bengali = state.quranData.find(function(a) { return a.sura === sura && a.aya === aya; });

    var html = '';
    if (arabic && arabic.ayat) {
      html += '<div class="verse-arabic">' + arabic.ayat + '</div>';
    }
    if (bengali && bengali.text) {
      html += '<div class="verse-translation"><strong>বাংলা অনুবাদ:</strong><br>' + bengali.text + '</div>';
    }
    if (tafsir && tafsir.text) {
      html += '<div class="tafsir-text"><strong>তাফসীর:</strong><br>' + tafsir.text + '</div>';
    } else {
      html += '<div class="tafsir-text"><p>এই আয়াতের তাফসীর এখনও যোগ করা হয়নি।</p></div>';
    }
    html += '<div class="tafsir-source"><strong>উৎস:</strong> ইবনে কাসিরের তাফসীর</div>';

    dom.tafsirTitle.textContent = 'সূরা ' + sura + ', আয়াত ' + aya + ' - তাফসীর';
    dom.tafsirBody.innerHTML = html;
    dom.tafsirModal.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeTafsirModal() {
    dom.tafsirModal.classList.remove('active');
    document.body.style.overflow = '';
  }

  // ==================== AUDIO ====================
  function playAudio(sura, aya) {
    var url = 'https://cdn.islamic.network/quran/audio/128/ar.alafasy/' + sura + '/' + aya + '.mp3';
    var audio = new Audio(url);
    audio.playbackRate = parseFloat(state.audioSettings.speed);
    audio.play().then(function() {
      addBotMessage('🎧 আয়াত তিলাওয়াত শোনা হচ্ছে...', 'info');
    }).catch(function() {
      addBotMessage('❌ অডিও প্লে করতে সমস্যা হয়েছে।', 'error');
    });
  }

  // ==================== COPY ====================
  function copyAyaText(sura, aya) {
    var ayaData = state.quranData.find(function(a) { return a.sura === sura && a.aya === aya; });
    var arabic = state.arabicData.find(function(a) { return a.sura === sura && a.VerseIDAr === aya; });
    var text = 'সূরা ' + sura + ', আয়াত ' + aya + '\n\n';
    if (arabic && arabic.ayat) text += arabic.ayat + '\n\n';
    if (ayaData) text += ayaData.text;

    navigator.clipboard.writeText(text).then(function() {
      addBotMessage('✅ কপি করা হয়েছে!', 'success');
    }).catch(function() {
      addBotMessage('❌ কপি করতে সমস্যা হয়েছে।', 'error');
    });
  }

  // ==================== HADITH FEATURE ====================
  function showRandomHadith() {
    var hadith = state.hadithData[Math.floor(Math.random() * state.hadithData.length)];
    var html = '<div class="hadith-card">';
    html += '<div class="hadith-text">' + hadith.text + '</div>';
    html += '<div class="hadith-translation"><strong>অনুবাদ:</strong> ' + hadith.translation + '</div>';
    if (hadith.explanation) {
      html += '<div style="font-size:0.8rem;margin:0.2rem 0;color:var(--text-light);"><strong>ব্যাখ্যা:</strong> ' + hadith.explanation + '</div>';
    }
    html += '<div class="hadith-source">📚 ' + hadith.source + ' | 🗣️ ' + hadith.narrator + '</div>';
    html += '</div>';
    addBotMessage(html, 'normal', true);
  }

  function showAllHadith() {
    var html = '<strong>📜 হাদিস সমূহ</strong><br><br>';
    state.hadithData.forEach(function(h, i) {
      html += '<div class="hadith-card" style="margin-bottom:0.4rem;">';
      html += '<div class="hadith-text">' + (i+1) + '. ' + h.text + '</div>';
      html += '<div class="hadith-translation"><strong>অনুবাদ:</strong> ' + h.translation + '</div>';
      if (h.explanation) {
        html += '<div style="font-size:0.75rem;margin:0.1rem 0;color:var(--text-light);"><strong>ব্যাখ্যা:</strong> ' + h.explanation + '</div>';
      }
      html += '<div class="hadith-source">📚 ' + h.source + ' | 🗣️ ' + h.narrator + '</div>';
      html += '</div>';
    });
    addBotMessage(html, 'normal', true);
  }

  // ==================== BLOG POSTS FEATURE ====================
  function showBlogPosts() {
    if (!state.blogPosts || state.blogPosts.length === 0) {
      addBotMessage('📝 বর্তমানে কোন ব্লগ পোস্ট নেই।', 'info');
      return;
    }

    var html = '<strong>📝 সাম্প্রতিক ব্লগ পোস্ট</strong><br><br>';
    state.blogPosts.slice(0, 5).forEach(function(post, i) {
      var postId = post.id || 'post-' + i;
      var isExpanded = state.expandedPosts[postId] || false;

      html += '<div class="blog-post-card" id="blog-post-' + postId + '">';
      html += '<div class="post-title" onclick="window.toggleBlogPost(\'' + postId + '\')">' + (i+1) + '. ' + post.title + '</div>';

      if (!isExpanded) {
        html += '<div class="post-excerpt">' + (post.summary || post.content.substring(0, 200) + '...') + '</div>';
      }

      if (isExpanded && post.content) {
        html += '<div class="post-full-content">' + post.content.replace(/\n/g, '<br>') + '</div>';
      }

      html += '<div class="post-meta">📅 ' + (post.published ? new Date(post.published).toLocaleDateString('bn-BD') : '') + ' | ✍️ ' + post.author + '</div>';
      html += '<div class="action-buttons">';

      if (!isExpanded && post.content && post.content.length > 100) {
        html += '<button class="action-btn primary" onclick="window.toggleBlogPost(\'' + postId + '\')">📖 পড়ুন</button>';
      } else if (isExpanded) {
        html += '<button class="action-btn outline" onclick="window.toggleBlogPost(\'' + postId + '\')">⬆️ সংক্ষেপ</button>';
      }

      if (post.link && post.link !== '#') {
        html += '<button class="action-btn gold" onclick="window.open(\'' + post.link + '\',\'_blank\')">🔗 লিংক</button>';
      }
      html += '<button class="action-btn outline" onclick="window.copyBlogPost(\'' + postId + '\')">📋 কপি</button>';
      html += '</div>';
      html += '</div>';
    });
    addBotMessage(html, 'normal', true);
  }

  function toggleBlogPostImpl(postId) {
    // Find the post by id
    var post = null;
    for (var i = 0; i < state.blogPosts.length; i++) {
      var p = state.blogPosts[i];
      var pId = p.id || 'post-' + i;
      if (pId === postId) {
        post = p;
        break;
      }
    }
    if (!post) return;

    state.expandedPosts[postId] = !state.expandedPosts[postId];
    // Find the most recent bot message that renders the blog list and
    // re-render it in place so the toggle reflects immediately.
    var messages = dom.messages.querySelectorAll('.message.bot');
    var lastBotMsg = messages[messages.length - 1];
    if (lastBotMsg) {
      var hasBlog = lastBotMsg.innerHTML.indexOf('সাম্প্রতিক ব্লগ পোস্ট') !== -1;
      if (hasBlog) {
        lastBotMsg.remove();
        showBlogPosts();
        return;
      }
    }
    showBlogPosts();
  }

  function copyBlogPostImpl(postId) {
    var post = null;
    for (var i = 0; i < state.blogPosts.length; i++) {
      var p = state.blogPosts[i];
      var pId = p.id || 'post-' + i;
      if (pId === postId) {
        post = p;
        break;
      }
    }
    if (!post) return;

    var text = post.title + '\n\n' + post.content;
    navigator.clipboard.writeText(text).then(function() {
      addBotMessage('✅ পোস্ট কপি করা হয়েছে!', 'success');
    }).catch(function() {
      addBotMessage('❌ কপি করতে সমস্যা হয়েছে।', 'error');
    });
  }

