    html += '<div class="prayer-item"><span class="name">সূর্যোদয়</span><span class="time">' + times.sunrise + '</span></div>';
    html += '<div class="prayer-item"><span class="name">জোহর</span><span class="time">' + times.dhuhr + '</span></div>';
    html += '<div class="prayer-item"><span class="name">আসর</span><span class="time">' + times.asr + '</span></div>';
    html += '<div class="prayer-item"><span class="name">মাগরিব</span><span class="time">' + times.maghrib + '</span></div>';
    html += '<div class="prayer-item"><span class="name">ইশা</span><span class="time">' + times.isha + '</span></div>';
