  // ==================== QUIZ FEATURE ====================
  function startQuiz() {
    var questions = [
      { q: "কুরআনের প্রথম সূরার নাম কি?", o: ["আল-ফাতিহা","আল-বাকারা","আল-ইখলাস","ইয়াসিন"], c: 0, e: "আল-ফাতিহা অর্থ 'উন্মোচনকারী', ৭ আয়াত।" },
      { q: "কুরআনে মোট কয়টি সূরা আছে?", o: ["114","100","125","99"], c: 0, e: "মোট ১১৪টি সূরা, ৮৬টি মাক্কী, ২৮টি মাদানী।" },
      { q: "আয়াতুল কুরসি কোন সূরায় আছে?", o: ["সূরা বাকারা","সূরা ইখলাস","সূরা ফাতিহা","সূরা ইয়াসিন"], c: 0, e: "সূরা বাকারার ২৫৫ নম্বর আয়াত।" },
      { q: "ইসলামের ৫টি স্তম্ভের মধ্যে প্রথমটি কি?", o: ["কালিমা","সালাত","জাকাত","রোজা"], c: 0, e: "কালিমা শাহাদাত হলো ইসলামের প্রথম স্তম্ভ।" }
    ];

    state.quizState = {
      questions: questions,
      current: 0,
      score: 0,
      total: questions.length
    };

    askQuizQuestion();
  }

  function askQuizQuestion() {
    if (!state.quizState) return;

    if (state.quizState.current >= state.quizState.total) {
      showQuizResult();
      return;
    }

    var q = state.quizState.questions[state.quizState.current];
    var html = '<div class="quiz-card">';
    html += '<div class="question">🧠 প্রশ্ন ' + (state.quizState.current + 1) + '/' + state.quizState.total + ': ' + q.q + '</div>';
    q.o.forEach(function(opt, i) {
      var letter = String.fromCharCode(65 + i);
      html += '<button class="option-btn" onclick="window.answerQuizOption(' + i + ')">' + letter + '. ' + opt + '</button>';
    });
    html += '</div>';
    addBotMessage(html, 'normal', true);
  }

  function answerQuizOptionImpl(selected) {
    if (!state.quizState) return;

    var q = state.quizState.questions[state.quizState.current];
    var correct = selected === q.c;

    if (correct) {
      state.quizState.score++;
      addBotMessage('✅ সঠিক উত্তর! 🎉<br><br>' + q.e, 'success');
    } else {
      addBotMessage('❌ ভুল উত্তর! সঠিক: ' + q.o[q.c] + '<br><br>' + q.e, 'error');
    }

    state.quizState.current++;
    setTimeout(askQuizQuestion, 2000);
  }

  function showQuizResult() {
    if (!state.quizState) return;

    var pct = Math.round((state.quizState.score / state.quizState.total) * 100);
    var msg = pct >= 80 ? '🎉 অসাধারণ! আপনি কুরআন সম্পর্কে গভীর জ্ঞান রাখেন।' : 
              pct >= 60 ? '👍 ভালো হয়েছে! আরও পড়াশোনা করুন।' : 
              '📚 আরও পড়ুন এবং শিখুন। আল্লাহ আপনাকে তাওফিক দান করুন।';

    var html = '<div class="quiz-card">';
    html += '<div class="result">📊 কুইজ রেজাল্ট</div>';
    html += '<div style="text-align:center;padding:0.2rem 0;">স্কোর: ' + state.quizState.score + '/' + state.quizState.total + '</div>';
    html += '<div style="text-align:center;padding:0.2rem 0;">পার্সেন্টেজ: ' + pct + '%</div>';
    html += '<div style="text-align:center;padding:0.2rem 0;">' + msg + '</div>';
    html += '<button onclick="window.startQuiz()" style="display:block;width:100%;padding:0.4rem;background:var(--gold-gradient);border:none;border-radius:var(--rounded);cursor:pointer;font-weight:600;font-family:var(--font-ui);color:var(--dark);font-size:0.85rem;">🔄 আবার চেষ্টা করুন</button>';
    html += '</div>';
    addBotMessage(html, 'normal', true);

    state.quizState = null;
  }

  // ==================== GREETING ====================
  function handleGreeting() {
    var responses = [
      'ওয়া আলাইকুম আসসালাম! কুরআন, তাফসীর, হাদিস, ব্লগ পোস্ট বা ইসলামিক জ্ঞান সম্পর্কে জানতে চান?',
      'আসসালামু আলাইকুম! কেমন আছেন? কীভাবে সাহায্য করতে পারি?',
      'ওয়া আলাইকুম আসসালাম! আল্লাহ আপনার দিন বরকতময় করুন।'
    ];
    addBotMessage(responses[Math.floor(Math.random() * responses.length)]);
  }

  // ==================== VOICE RECOGNITION ====================
  function initVoice() {
    if (!('webkitSpeechRecognition' in window || 'SpeechRecognition' in window)) {
      addBotMessage('❌ আপনার ব্রাউজার ভয়েস সাপোর্ট করে না।', 'error');
      return;
    }

    var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    state.recognition = new SR();
    state.recognition.lang = 'bn-BD';
    state.recognition.continuous = false;
    state.recognition.interimResults = false;

    state.recognition.onstart = function() {
      state.isVoiceActive = true;
      dom.voiceBtn.innerHTML = '🔴 রেকর্ডিং';
      addBotMessage('🎤 কথা বলুন...', 'info');
    };

    state.recognition.onresult = function(e) {
      var text = e.results[0][0].transcript;
      dom.input.value = text;
      processQuery(text);
    };

    state.recognition.onerror = function(e) {
      addBotMessage('❌ ভয়েস ত্রুটি: ' + e.error, 'error');
      state.isVoiceActive = false;
      dom.voiceBtn.innerHTML = '🎤 ভয়েস';
    };

    state.recognition.onend = function() {
      state.isVoiceActive = false;
      dom.voiceBtn.innerHTML = '🎤 ভয়েস';
    };
  }

  function toggleVoice() {
    if (!state.recognition) initVoice();
    if (!state.recognition) return;

    if (state.isVoiceActive) {
      state.recognition.stop();
    } else {
      try {
        state.recognition.start();
      } catch (e) {
        addBotMessage('❌ মাইক্রোফোন এক্সেস সমস্যা।', 'error');
      }
    }
  }

  // ==================== THEME ====================
  function toggleTheme() {
    state.isDark = !state.isDark;
    document.documentElement.setAttribute('data-theme', state.isDark ? 'dark' : 'light');
    localStorage.setItem('quranTheme', state.isDark ? 'dark' : 'light');
    dom.themeIcon.textContent = state.isDark ? '☀️' : '🌙';
  }

  function loadTheme() {
    var saved = localStorage.getItem('quranTheme');
    if (saved === 'dark') {
      state.isDark = true;
      document.documentElement.setAttribute('data-theme', 'dark');
      dom.themeIcon.textContent = '☀️';
    }
  }

  // ==================== SETTINGS ====================
  function loadSettings() {
    var saved = localStorage.getItem('quranChatSettings');
    if (saved) {
      try {
        var settings = JSON.parse(saved);
        document.getElementById('bengali-font-size').value = settings.bengaliFontSize || '16px';
        document.getElementById('arabic-font-size').value = settings.arabicFontSize || '1.6rem';
        document.getElementById('audio-speed').value = settings.audioSpeed || '1';
        document.getElementById('auto-play-audio').checked = settings.autoPlayAudio || false;
        document.getElementById('show-transliteration').checked = settings.showTransliteration || false;

        state.audioSettings.speed = settings.audioSpeed || '1';
        state.audioSettings.autoPlay = settings.autoPlayAudio || false;
        state.displaySettings.showTransliteration = settings.showTransliteration || false;

        applySettings();
      } catch (e) {}
    }
  }

  function saveSettings() {
    var settings = {
      bengaliFontSize: document.getElementById('bengali-font-size').value,
      arabicFontSize: document.getElementById('arabic-font-size').value,
      audioSpeed: document.getElementById('audio-speed').value,
      autoPlayAudio: document.getElementById('auto-play-audio').checked,
      showTransliteration: document.getElementById('show-transliteration').checked
    };
    localStorage.setItem('quranChatSettings', JSON.stringify(settings));

    state.audioSettings.speed = settings.audioSpeed;
    state.audioSettings.autoPlay = settings.autoPlayAudio;
    state.displaySettings.showTransliteration = settings.showTransliteration;

    applySettings();
  }

  function applySettings() {
    var chat = document.getElementById('chatbot-fullpage');
    chat.style.setProperty('--bengali-font-size', document.getElementById('bengali-font-size').value);
    chat.style.setProperty('--arabic-font-size', document.getElementById('arabic-font-size').value);
  }

  function resetSettings() {
    document.getElementById('bengali-font-size').value = '16px';
    document.getElementById('arabic-font-size').value = '1.6rem';
    document.getElementById('audio-speed').value = '1';
    document.getElementById('auto-play-audio').checked = false;
    document.getElementById('show-transliteration').checked = false;
    saveSettings();
    addBotMessage('✅ সেটিংস রিসেট করা হয়েছে!', 'success');
  }

  // ==================== SURA LIST ====================
  function loadSuraList() {
    var names = [
      "আল-ফাতিহা","আল-বাকারা","আল-ইমরান","আন-নিসা","আল-মায়িদাহ",
      "আল-আন'আম","আল-আ'রাফ","আল-আনফাল","আত-তাওবাহ","ইউনুস",
      "হুদ","ইউসুফ","আর-রাদ","ইবরাহিম","আল-হিজর","আন-নাহল",
      "আল-ইসরা","আল-কাহফ","মারইয়াম","তাহা","আল-আম্বিয়া",
      "আল-হাজ্জ","আল-মুমিনুন","আন-নূর","আল-ফুরকান","আশ-শু'আরা",
      "আন-নামল","আল-কাসাস","আল-আনকাবুত","আর-রুম","লুকমান",
      "আস-সাজদাহ","আল-আহযাব","সাবা","ফাতির","ইয়াসিন",
      "আস-সাফফাত","সাদ","আয-যুমার","গাফির","ফুসসিলাত",
      "আশ-শুরা","আয-যুখরুফ","আদ-দুখান","আল-জাসিয়াহ","আল-আহকাফ",
      "মুহাম্মদ","আল-ফাতহ","আল-হুজুরাত","কাফ","আয-যারিয়াত",
      "আত-তুর","আন-নাজম","আল-কামার","আর-রহমান","আল-ওয়াকিয়াহ",
      "আল-হাদীদ","আল-মুজাদিলাহ","আল-হাশর","আল-মুমতাহিনাহ","আস-সাফ",
      "আল-জুমু'আহ","আল-মুনাফিকুন","আত-তাগাবুন","আত-তালাক","আত-তাহরীম",
      "আল-মুলক","আল-কালাম","আল-হাক্কাহ","আল-মা'আরিজ","নূহ",
      "আল-জিন","আল-মুজাম্মিল","আল-মুদ্দাস্সির","আল-কিয়ামাহ","আল-ইনসান",
      "আল-মুরসালাত","আন-নাবা","আন-নাজি'আত","আবাসা","আত-তাকভীর",
      "আল-ইনফিতার","আল-মুতাফফিফীন","আল-ইনশিকাক","আল-বুরূজ","আত-তারিক",
      "আল-আ'লা","আল-গাশিয়াহ","আল-ফাজর","আল-বালাদ","আশ-শামস",
      "আল-লাইল","আদ-দুহা","আল-ইনশিরাহ","আত-তীন","আল-আলাক",
      "আল-কাদর","আল-বাইয়্যিনাহ","আয-যিলযাল","আল-আদিয়াত","আল-কারি'আহ",
      "আত-তাকাসুর","আল-আসর","আল-হুমাজাহ","আল-ফীল","কুরাইশ",
      "আল-মাউন","আল-কাওসার","আল-কাফিরুন","আন-নাসর","আল-মাসাদ",
      "আল-ইখলাস","আল-ফালাক","আন-নাস"
    ];

    var html = '';
    names.forEach(function(name, i) {
      var num = i + 1;
      var count = getSurahAyahCount(num);
      html += '<div class="sura-item" data-sura="' + num + '"><strong>' + num + '</strong><br>' + name + '<small>' + count + '</small></div>';
    });

    dom.suraGrid.innerHTML = html;

    dom.suraGrid.querySelectorAll('.sura-item').forEach(function(el) {
      el.addEventListener('click', function() {
        var sura = this.getAttribute('data-sura');
        dom.input.value = sura + ':1';
        dom.input.focus();
        closeSuraPanel();
        processQuery(sura + ':1');
      });
    });
  }

  function filterSuraList(query) {
    var items = dom.suraGrid.querySelectorAll('.sura-item');
    var q = query.toLowerCase();
    items.forEach(function(item) {
      var text = item.textContent.toLowerCase();
      item.style.display = text.indexOf(q) !== -1 ? '' : 'none';
    });
  }

  function openSuraPanel() {
    dom.suraPanel.classList.add('active');
    document.body.style.overflow = 'hidden';
    dom.suraSearch.focus();
  }

  function closeSuraPanel() {
    dom.suraPanel.classList.remove('active');
    document.body.style.overflow = '';
  }

  function openSettingsPanel() {
    dom.settingsPanel.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeSettingsPanel() {
    dom.settingsPanel.classList.remove('active');
    document.body.style.overflow = '';
  }

  // ==================== QUICK ACTIONS ====================
  function handleQuickAction(action) {
    switch(action) {
      case 'start':
        addBotMessage('💬 চ্যাট শুরু হয়েছে! আপনি প্রশ্ন করতে পারেন:\n• সূরা:আয়াত (যেমন: 2:255)\n• হাদিস দেখতে "হাদিস" লিখুন\n• ব্লগ পোস্ট দেখতে "ব্লগ" লিখুন\n• নামাজের সময় জানতে "নামাজ" লিখুন\n• কুইজ খেলতে "কুইজ" লিখুন\n• জ্ঞান দেখতে "জ্ঞান" লিখুন', 'info');
        break;
      case 'popular':
        showPopularAyat();
        break;
      case 'prayer':
        showPrayerTimes();
        break;
      case 'hadith':
        showRandomHadith();
        break;
      case 'blog':
        showBlogPosts();
        break;
      case 'quiz':
        startQuiz();
        break;
      case 'knowledge':
        showKnowledgeBase();
        break;
      case 'guide':
        showGuide();
        break;
      case 'about':
        addBotMessage('<strong>🤖 কুরআন বট</strong><br><br>সংস্করণ: ৫.০<br>ডেভেলপার: আক্তারুজ্জামান মোল্লা<br><br>🎯 বৈশিষ্ট্য:<br>• কুরআন আয়াত ও তাফসীর<br>• হাদিস সংগ্রহ (ব্যাখ্যাসহ)<br>• ব্লগ পোস্ট পড়া (পূর্ণ)<br>• সালাতের সময়<br>• ইন্টারেক্টিভ কুইজ<br>• ইসলামিক জ্ঞান ভাণ্ডার<br>• ভয়েস রেকগনিশন<br>• অডিও তিলাওয়াত<br>• সূরা সার্চ<br>• ডার্ক/লাইট মোড', 'normal', true);
        break;
      default:
        addBotMessage('❓ অজ্ঞাত কমান্ড', 'error');
    }
  }

  function showPopularAyat() {
    var popular = [
      { sura: '1', aya: '1', name: 'সূরা ফাতিহা' },
      { sura: '2', aya: '255', name: 'আয়াতুল কুরসি' },
      { sura: '36', aya: '1', name: 'সূরা ইয়াসিন' },
      { sura: '67', aya: '1', name: 'সূরা মুলক' },
      { sura: '112', aya: '1', name: 'সূরা ইখলাস' },
      { sura: '55', aya: '1', name: 'সূরা রহমান' }
    ];

    var html = '<strong>⭐ জনপ্রিয় আয়াত</strong><br><br>';
    popular.forEach(function(p, i) {
      html += '<button onclick="window.selectAya(\'' + p.sura + '\',\'' + p.aya + '\')" style="display:block;width:100%;margin:3px 0;padding:4px 8px;border:2px solid var(--primary);border-radius:8px;cursor:pointer;background:var(--white);text-align:left;font-family:var(--font-ui);font-weight:600;font-size:0.8rem;">' + (i+1) + '. ' + p.name + '<br><small style="color:var(--gray-dark);font-weight:400;">সূরা ' + p.sura + ', আয়াত ' + p.aya + '</small></button>';
    });
    addBotMessage(html, 'normal', true);
  }

  // ==================== GLOBAL EXPOSURE ====================
  // NOTE: these are the single source of truth for the inline onclick
  // handlers used in generated HTML (blog cards, quiz options, etc).
  // Do NOT redefine them again below this block, or the real
  // implementations get silently replaced with no-ops and clicking
  // "পড়ুন", quiz options, etc. will stop working.
  window.selectAya = function(sura, aya) {
    var result = state.quranData.find(function(a) { return a.sura === sura && a.aya === aya; });
    if (result) {
      state.currentAya = result;
      displayAyaResult(result);
      if (state.audioSettings.autoPlay) {
        setTimeout(function() { playAudio(sura, aya); }, 1000);
      }
    }
  };

  window.showTafsir = showTafsirModal;
  window.playAudio = playAudio;
  window.copyAya = copyAyaText;
  window.answerQuizOption = answerQuizOptionImpl;
  window.toggleBlogPost = toggleBlogPostImpl;
  window.copyBlogPost = copyBlogPostImpl;
  window.startQuiz = startQuiz;

  // ==================== EVENT BINDING ====================
  function init() {
    loadQuranData();
    loadSettings();
    loadTheme();
    loadSuraList();

    dom.sendBtn.addEventListener('click', function() {
      processQuery(dom.input.value);
    });

    dom.input.addEventListener('keypress', function(e) {
      if (e.key === 'Enter') {
        e.preventDefault();
        processQuery(dom.input.value);
      }
    });

    dom.clearBtn.addEventListener('click', clearChat);

    dom.tafsirBtn.addEventListener('click', function() {
      if (state.currentAya) {
        showTafsirModal(state.currentAya.sura, state.currentAya.aya);
      } else {
        addBotMessage('⚠️ প্রথমে একটি আয়াত নির্বাচন করুন বা সূরা:আয়াত লিখুন।', 'error');
      }
    });

    dom.voiceBtn.addEventListener('click', toggleVoice);
    dom.themeToggle.addEventListener('click', toggleTheme);

    dom.suraPanelBtn.addEventListener('click', openSuraPanel);
    dom.closeSura.addEventListener('click', closeSuraPanel);
    dom.suraSearch.addEventListener('input', function(e) {
      filterSuraList(e.target.value);
    });

    dom.settingsPanelBtn.addEventListener('click', openSettingsPanel);
    dom.closeSettings.addEventListener('click', closeSettingsPanel);

    document.querySelectorAll('#bengali-font-size, #arabic-font-size, #audio-speed, #auto-play-audio, #show-transliteration').forEach(function(el) {
      el.addEventListener('change', saveSettings);
    });

    document.getElementById('reset-settings').addEventListener('click', resetSettings);

    dom.closeTafsir.addEventListener('click', closeTafsirModal);
    dom.tafsirModal.addEventListener('click', function(e) {
      if (e.target === dom.tafsirModal) closeTafsirModal();
    });

    document.querySelectorAll('.quick-action-premium').forEach(function(btn) {
      btn.addEventListener('click', function() {
        var action = this.getAttribute('data-action');
        handleQuickAction(action);
      });
    });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        closeTafsirModal();
        closeSuraPanel();
        closeSettingsPanel();
      }
    });

    dom.input.focus();
    console.log('🤖 কুরআন বট ৫.০ লোড হয়েছে!');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();
